import{j as e}from"./index-Cvn8XixQ.js";import{G as t}from"./GuidePageLayout-DjCFcGug.js";import"./PageBanner-C2RyqhZh.js";import"./Breadcrumbs-C1y9bcgc.js";import"./chevron-right-B7ezrMbL.js";import"./ServicePageLayout-DL5HiLt9.js";import"./button-W0vxHA79.js";function l(){return e.jsx(t,{"code-path":"src\\pages\\guides\\UssdCodeCost.tsx:5:5",title:"USSD Code Cost in Kenya (2026)",subtitle:"Shared vs dedicated USSD pricing — a buyer's guide",description:"How much does a USSD code cost in Kenya? This guide breaks down shared and dedicated USSD shortcode pricing, the CAK allocation process, per-session end-user charges, and what to budget for a USSD service — using MobiWave's published rates.",breadcrumbLabel:"USSD Code Cost",updated:"August 2026",intro:"USSD is the most inclusive channel in Kenya — it runs on every feature phone with no internet. But pricing is easy to misjudge because the business pays a service fee while the subscriber pays a per-session carrier charge. This guide separates the two so you can budget accurately.",checklist:["Decision: shared (sub-keyword) or dedicated (own code)","Registered Kenyan business + KRA PIN","Signed CAK shortcode application letter","Budget for the service fee (not just setup)","Plan for the end-user per-session charge","API or webhook for your menu logic"],steps:[{step:"1",title:"Pick shared or dedicated",description:"Shared USSD runs on MobiWave’s allocated code as a sub-keyword — cheapest and fastest. Dedicated is your own branded code (e.g. *123#) for full control and recall."},{step:"2",title:"Budget the service fee",description:"Shared: KES 11,000 setup + KES 8,000/month (+VAT). Dedicated: KES 40,000 up-front + KES 40,000/month (+VAT). Test-bed: KES 32,000 for 30 days (+VAT)."},{step:"3",title:"Apply through the CAK",description:"Shortcodes are allocated by the Communications Authority of Kenya. MobiWave prepares and submits the application with your business documents so you skip the paperwork."},{step:"4",title:"Account for end-user cost",description:"The carrier bills your customer a per-session charge (typically KES 1–5 depending on network and session length) on their airtime. Your business does not absorb this."},{step:"5",title:"Build in the test-bed",description:"Use the 30-day test-bed (KES 32,000 +VAT) to develop menus and validate sessions before real traffic hits your systems."},{step:"6",title:"Go live and bundle",description:"Point menus at your API, then add M-Pesa STK Push, SMS and WhatsApp from the same MobiWave account for one billing line."}],comparison:{headers:["MobiWave","Africa's Talking","Celcom Africa","Twilio"],note:"MobiWave figures are published rates (VAT extra). Competitor USSD is typically quote-based. Twilio has no native Kenya USSD shortcode product.",rows:[{name:"Shared USSD",cells:[{text:"KES 11,000 setup + KES 8,000/mo",highlight:!0},{text:"Available (quote)"},{text:"Available"},{text:"Not supported"}]},{name:"Dedicated USSD",cells:[{text:"KES 40,000 + KES 40,000/mo",highlight:!0},{text:"Available (quote)"},{text:"Available"},{text:"Not supported"}]},{name:"Test-bed",cells:[{text:"KES 32,000 / 30 days",highlight:!0},{text:"Yes"},{text:"Yes"},{text:"N/A"}]},{name:"End-user per-session charge",cells:[{text:"Billed to subscriber",highlight:!0},{text:"Billed to subscriber"},{text:"Billed to subscriber"},{text:"N/A"}]},{name:"M-Pesa STK from menu",cells:[{text:"Native, bundled",highlight:!0},{text:"Add-on"},{text:"Yes"},{text:"No"}]},{name:"Local 24/7 support",cells:[{text:"Phone + WhatsApp",highlight:!0},{text:"Developer-only"},{text:"Business hours"},{text:"No local team"}]}]},faqs:[{question:"How much does a USSD code cost in Kenya in 2026?",answer:"Shared USSD is KES 11,000 setup + KES 8,000/month (+VAT). Dedicated is KES 40,000 up-front + KES 40,000/month (+VAT). A 30-day test-bed is KES 32,000 (+VAT). All prices are exclusive of VAT."},{question:"Who pays the per-session charge?",answer:"The end user. The carrier bills your customer a per-session charge (typically KES 1–5) on their airtime. Your business pays only the MobiWave service fee."},{question:"Is shared or dedicated cheaper?",answer:"Shared is far cheaper (KES 11,000 setup vs KES 40,000) and goes live faster. Choose dedicated only when you need your own branded code and full keyword control."},{question:"How long does it take to get a code?",answer:"Shared codes can be live within days on MobiWave’s pool. Dedicated codes need CAK approval, typically several weeks. Build in the test-bed in parallel."},{question:"Do I need a CAK application?",answer:"Yes — shortcodes are allocated by the Communications Authority of Kenya. MobiWave handles the application for you with your business registration and letterhead."},{question:"Can I collect M-Pesa inside USSD?",answer:"Yes. MobiWave triggers an STK Push from any menu step and reconciles the result, so a feature-phone user can pay without internet."},{question:"Do users need internet?",answer:"No. USSD runs over the GSM signalling channel on every phone — the core advantage for rural and low-connectivity audiences."},{question:"Can menus be in Swahili?",answer:"Yes. Multi-language menus including Swahili are supported, selectable by the subscriber in the first level."},{question:"Is there an API?",answer:"Yes. Each menu step calls your REST endpoint with the session id and input; MobiWave manages session state, timeouts and analytics."},{question:"How is MobiWave different from Africa’s Talking for USSD?",answer:"Both provide USSD. MobiWave bundles M-Pesa STK Push, SMS and WhatsApp on one account with managed CAK onboarding and 24/7 local support; Africa’s Talking is developer-self-service."}],relatedRoutes:[{label:"USSD Codes",href:"/services/ussd-codes"},{label:"M-Pesa STK Push API",href:"/guides/mpesa-stk-push-api-kenya"},{label:"Shortcodes & Sender IDs",href:"/services/shortcodes"}]})}export{l as UssdCodeCostGuide};
